  $materia_medica_json${"id":"MED-002","slug":"cinchona-officinalis","name":"Cinchona Officinalis","commonName":"Peruvian Bark","scientificName":"Cinchona officinalis","abbreviation":"Chin.","synonyms":["China","China Officinalis","Peruvian Bark","Jesuit's Bark","Quinine Bark"],"source":"Plant","origin":"Bark of Cinchona species native to the eastern slopes of the Andes in South America","naturalOrder":"Rubiaceae (formerly Cinchonaceae)","family":"Rubiaceae (madder family)","kingdom":"Plantae","habitat":"Mountain forests of Peru, Bolivia and Ecuador; cultivated in India, Sri Lanka, Java and parts of Africa","partUsed":"Dried bark of the stem and branches","preparation":"Mother tincture and attenuations prepared from the dried bark according to traditional homeopathic pharmacopoeial methods","chemicalConstituents":["Cinchotannic acid","Quinic acid","Volatile oil","Resinous and bitter principles"],"alkaloids":["Quinine (principal alkaloid)","Quinidine","Cinchonine","Cinchonidine"],"generalAnalysis":"A plant remedy from Peruvian bark whose traditional picture centres on profound debility following the loss of vital fluids, strongly marked periodicity, and a nervous erethism with hypersensitivity to touch, pain and draughts. The classical sources place intermittent fever, tympanitic abdominal distension and haemorrhage with weakness within its sphere.","sphereOfAction":["Nervous system","Digestive system","Spleen and liver","Blood and haemorrhages","Musculoskeletal system"],"drugPicture":{"generalPicture":"A picture of depletion: the patient is weak, pale and oversensitive after haemorrhage, diarrhoea, sexual excesses or other exhausting discharges. Complaints return at regular intervals, the slightest touch is intolerable, and the body feels as though it has been bruised.","generalCharacteristics":["Debility from exhausting discharges or loss of vital fluids","Periodicity, classically every other day","Oversensitiveness to the slightest touch and to draughts","Tympanitic distension of the abdomen","Haemorrhages accompanied by trembling and ringing in the ears"],"typicalConstitution":"Debilitated, anaemic and hypersensitive constitution with a pale face and low tolerance for fluid loss","temperament":"Apathetic and despondent, yet nervous and over-reactive","generalTendencies":["Debility after loss of fluids","Periodic return of symptoms","Flatulent distension","Haemorrhagic tendency"],"characteristicFeatures":["Symptoms recur every other day","Slightest touch aggravates, while hard pressure relieves","Abdominal tympany appearing early in the illness","Weakness out of proportion to the apparent complaint"]},"keySymptoms":{"keynotes":["Debility from exhausting discharges or loss of vital fluids","Marked periodicity, especially symptoms returning every other day","Extreme sensitiveness to touch; hard pressure ameliorates","Tympanitic distension of the abdomen","Intermittent fever with thirst and profuse debilitating sweat"],"guidingSymptoms":["Weakness, trembling and ringing in the ears after haemorrhage","Pains as if the limbs and joints were sprained, worse from slight touch","Hacking cough after every meal","Headache as if the skull would burst","Flatulent dyspepsia accompanying other complaints"],"characteristicSymptoms":["Every other day periodicity","Slightest touch aggravates; hard pressure ameliorates","Scalp sensitive, worse from combing the hair","Post-operative gas pains not relieved by passing flatus","Face flushed after haemorrhage or loss of vital fluids"],"indicatingSymptoms":["Debility with hypersensitivity to touch","Complaints recurring at a regular hour or on alternate days","Anaemia and prostration after haemorrhage or fluid loss"]},"mind":{"general":["Apathetic and indifferent","Taciturn and despondent","Disobedient and averse to being directed","Ideas crowd the mind and prevent sleep"],"sadness":["Despondency with indifference to surroundings"]},"physicalGenerals":{"constitution":"Debilitated, anaemic and sensi