  $materia_medica_json${"id":"MED-003","slug":"cuprum-metallicum","name":"Cuprum Metallicum","commonName":"Copper","scientificName":"Cuprum metallicum (Cu)","abbreviation":"Cupr.","synonyms":["Copper","Metallic Copper","Cuprum"],"source":"Mineral","origin":"Metallic copper obtained from copper ores and native copper deposits","naturalOrder":"Native metal","family":"Transition metal (Group 11)","kingdom":"Mineral","habitat":"Found native and in copper ores worldwide","partUsed":"Pure metallic copper","preparation":"Trituration of pure metallic copper, followed by successive attenuations","chemicalConstituents":["Copper (Cu), essentially pure in the homeopathic preparation"],"generalAnalysis":"A mineral remedy whose traditional picture is dominated by violent, spasmodic and convulsive phenomena. Cramps and convulsions classically begin in the fingers and toes and spread centrally, with blueness and coldness of the surface, intense nausea, and a striking amelioration from drinking cold water.","sphereOfAction":["Nervous system","Muscular system","Gastrointestinal system","Respiratory system","Circulatory system"],"drugPicture":{"generalPicture":"A picture of violent spasm. The patient is seized by cramps or convulsions that begin in the extremities, with piercing cries, a bluish or livid face, cold hands and intense nausea. The attacks recur periodically and in groups, and a swallow of cold water often brings relief.","generalCharacteristics":["Spasms and cramps of a violent, contractive character","Convulsions beginning in the fingers and toes","Thumbs clenched into the palms during spasms","Blueness of the face, lips and nails with coldness","Nausea and vomiting relieved by drinking cold water","Symptoms appear periodically and in groups"],"typicalConstitution":"Spasmodic and irritable constitution, seen in children as well as in debilitated or prematurely aged adults","temperament":"Anxious, restless and easily thrown into violent reaction","generalTendencies":["Spa